const tasks = await query('com.example.type.task');
const docs = tasks.filter(t => /docs/i.test(t.title ?? ''));
for (const t of docs) {
  update(t, (o) => { o.status = 'done'; });
  print('closed:', t.title);
}
await flush();
const after = await query('com.example.type.task');
print('done count:', after.filter(t => t.status === 'done').length);
